import json
from pathlib import Path
# Custom amd64 allow-list. CUDA ioctl remains allowed; Linux actual capability proof pending.
names='accept accept4 access arch_prctl bind brk capget chdir chmod clock_getres clock_gettime clock_nanosleep clone close close_range connect copy_file_range dup dup2 dup3 epoll_create epoll_create1 epoll_ctl epoll_pwait epoll_pwait2 epoll_wait eventfd eventfd2 execve exit exit_group faccessat faccessat2 fadvise64 fallocate fchdir fchmod fchmodat fcntl fdatasync flock fstat fstatfs fsync ftruncate futex futex_waitv getcwd getdents getdents64 getegid geteuid getgid getgroups getpeername getpid getppid getrandom getresgid getresuid getrlimit getrusage getsockname getsockopt gettid gettimeofday getuid ioctl kill lseek madvise membarrier memfd_create mincore mkdir mkdirat mlock mlock2 mlockall mmap mprotect mremap msync munlock munlockall munmap nanosleep newfstatat open openat pause pipe pipe2 poll ppoll prctl pread64 preadv preadv2 prlimit64 pselect6 pwrite64 pwritev pwritev2 read readlink readlinkat readv recvfrom recvmmsg recvmsg rename renameat renameat2 restart_syscall rmdir rseq rt_sigaction rt_sigpending rt_sigprocmask rt_sigqueueinfo rt_sigreturn rt_sigsuspend rt_sigtimedwait rt_tgsigqueueinfo sched_getaffinity sched_getparam sched_getscheduler sched_setaffinity sched_yield select sendmsg sendmmsg sendto set_robust_list set_tid_address setrlimit setsockopt shutdown sigaltstack socketpair stat statfs statx symlink symlinkat sysinfo tgkill time timer_create timer_delete timer_gettime timer_settime timerfd_create timerfd_gettime timerfd_settime times truncate umask uname unlink unlinkat utimensat vfork wait4 waitid write writev'.split()
# clone namespace flags are prohibited; simple threads/fork remain supported.
names.remove('clone')
rules=[{'names':names,'action':'SCMP_ACT_ALLOW'},{'names':['socket'],'action':'SCMP_ACT_ALLOW','args':[{'index':0,'value':1,'op':'SCMP_CMP_EQ'}]},{'names':['clone'],'action':'SCMP_ACT_ALLOW','args':[{'index':0,'value':2114060416,'valueTwo':0,'op':'SCMP_CMP_MASKED_EQ'}]}]
d={'defaultAction':'SCMP_ACT_ERRNO','defaultErrnoRet':1,'architectures':['SCMP_ARCH_X86_64'],'syscalls':rules}
p=Path(__file__).resolve().parent/'isolation/seccomp.json';p.write_text(json.dumps(d,indent=2)+'\n',encoding='utf-8')
